$internalSecret=(string)($config['app']['backup_cron_secret']??'');
$internalRequest=$internalSecret!=='' && !str_contains($internalSecret,'GENERATE') && hash_equals($internalSecret,(string)($_SERVER['HTTP_X_CLOUCOMAI_BACKUP_CRON']??''));
if($internalRequest){$internalUserId=(int)($_SERVER['HTTP_X_CLOUCOMAI_BACKUP_USER']??0);$st=db()->prepare('SELECT id,user_id,name,email,mobile,gender,account_status FROM users WHERE id=? LIMIT 1');$st->execute([$internalUserId]);$user=$st->fetch();if(!$user||$user['account_status']!=='active')fail('Account unavailable',404);}else{$user=auth_user();}
